    allowEmptyStaticShell,
    runInstantValidation,
    isFallbackUpgradeable,
    notFoundParams,
    experimental: {
      ...commonRenderOpts.experimental,
      isRoutePPREnabled,
    },
    renderResumeDataCache,
  }

