/**
 * Renders & exports a page associated with the /app directory
 */
export async function exportAppPage(
  req: MockedRequest,
  res: MockedResponse,
  requestUrl: string,
  page: string,
  path: string,
  pathname: string,
  query: NextParsedUrlQuery,
  fallbackRouteParams: OpaqueFallbackRouteParams | null,
  partialRenderOpts: Omit<RenderOpts, keyof RequestLifecycleOpts>,
  htmlFilepath: string,
  debugOutput: boolean,
  isDynamicError: boolean,
  fileWriter: MultiFileWriter,
  sharedContext: AppSharedContext,
  routeMatch: RouteMatch,
  routeCache?: RouteCacheMetadata
): Promise<ExportRouteResult> {
  const afterRunner = new AfterRunner()

  const renderOpts: RenderOpts = {
    ...partialRenderOpts,
    waitUntil: afterRunner.context.waitUntil,
    onClose: afterRunner.context.onClose,
    onAfterTaskError: afterRunner.context.onTaskError,
  }

  let isDefaultNotFound = false
  let isDefaultGlobalError = false
  // If the page is `/_not-found`, then we should update the page to be `/404`.
  if (page === UNDERSCORE_NOT_FOUND_ROUTE_ENTRY) {
    isDefaultNotFound = true
    pathname = '/404'
  }
  // If the page is `/_global-error`, then we should update the page to be `/500`.
  if (page === UNDERSCORE_GLOBAL_ERROR_ROUTE_ENTRY) {
    isDefaultGlobalError = true
    pathname = '/500'
  }

  try {
    const nextReq = new NodeNextRequest(req)
    const parsedRequestHeaders: ParsedRequestHeaders = parseRequestHeaders(
      nextReq.headers,
      {
        isRoutePPREnabled: renderOpts.experimental.isRoutePPREnabled === true,
        previewModeId: renderOpts.previewProps?.previewModeId,
      }
    )
    const result = await lazyPrerenderAppPage(
      nextReq,
      new NodeNextResponse(res),
      requestUrl,
      pathname,
      query,
      fallbackRouteParams,
      renderOpts,
      undefined, // dev
      sharedContext,
      routeMatch,
      parsedRequestHeaders,
      getServerActionRequestMetadata(nextReq)
    )

    if ('error' in result) {
      throw result.error
    }

